// F-03 unit tests — TEST-03-01, TEST-03-03, TEST-03-04 (docs/sprints/sprint-2/F-03-teams.md §7)
// Pure domain rules: no database. TEST-03-02 (join code format) is an API/DB test, because the codes are
// generated by the database function cpms_join_code() (contract v1.1).
import { describe, it, expect } from 'vitest';
import { validateTeamName, normalizeJoinCode, canJoin, hasMinimumSize, isMembershipLocked } from '../src/teams/rules.js';

describe('TEST-03-01 validateTeamName and normalizeJoinCode (AC-03-02, AC-03-06)', () => {
  it('trims the team name and ignores other fields', () => {
    expect(validateTeamName({ name: '  Team Gamma ', userId: 999 })).toEqual({ ok: true, value: { name: 'Team Gamma' } });
  });

  it.each([[undefined], [''], ['   '], [42], ['x'.repeat(61)]])('rejects the name %j and names the field', (name) => {
    const r = validateTeamName({ name });
    expect(r.ok).toBe(false);
    expect(Object.keys(r.details)).toEqual(['name']);
  });

  it('accepts a 60-character name (boundary)', () => {
    expect(validateTeamName({ name: 'x'.repeat(60) }).ok).toBe(true);
  });

  it('normalises a join code to upper case without spaces', () => {
    expect(normalizeJoinCode({ joinCode: 'alpha234' })).toEqual({ ok: true, value: 'ALPHA234' });
    expect(normalizeJoinCode({ joinCode: ' ALPHA234 ' })).toEqual({ ok: true, value: 'ALPHA234' });
  });

  it.each([[undefined], [''], ['ALPHA23'], ['ALPHA2345'], ['ALPHA2O4'], ['ALPHI234'], ['ALPHA210'], [12345678]])(
    'rejects the malformed code %j and names the field',
    (joinCode) => {
      const r = normalizeJoinCode({ joinCode });
      expect(r.ok).toBe(false);
      expect(Object.keys(r.details)).toEqual(['joinCode']);
    },
  );
});

describe('TEST-03-03 team size (AC-03-05, AC-03-09, BR-07)', () => {
  it('a team can be joined while it is below the maximum; the max-th member is the last one', () => {
    expect(canJoin(2, 3)).toBe(true);
    expect(canJoin(3, 3)).toBe(false);
    expect(canJoin(4, 3)).toBe(false);
  });

  it('a proposal can be submitted only with at least the minimum size (boundary = minimum)', () => {
    expect(hasMinimumSize(1, 2)).toBe(false);
    expect(hasMinimumSize(2, 2)).toBe(true);
    expect(hasMinimumSize(3, 2)).toBe(true);
  });
});

describe('TEST-03-04 isMembershipLocked (AC-03-08, BR-08)', () => {
  it.each([
    [[], false],
    [['REJECTED'], false],
    [['REJECTED', 'SUBMITTED'], false],
    [['DRAFT'], false],
    [['APPROVED'], true],
    [['REJECTED', 'APPROVED'], true],
  ])('statuses %j → locked %s', (statuses, locked) => {
    expect(isMembershipLocked(statuses)).toBe(locked);
  });
});
